<template>
  <div class="hello">
    <!-- <h1>{{ msg }}</h1> -->
    <h1>Rose's Writer Helper</h1>
    <br/>
    <p class="disclaimer">
      tl;dr <strong>Not a replacement for an editor.</strong>
    </p>
    <br/><br/>
    <!-- <p class="disclaimer">
      Some notes:
      Simple text matching guidance for your writing. Reminder, they are suggestions, always stay true to your writing.
      None of the text you enter <strong>ever</strong> leaves your computer. <strong>No AI</strong> usage. (This means there can be false positives and missed words, but it's a start.)
    </p> -->
    <p class="disclaimer">
      Some notes:
    </p>
    <br/>
    <ul class="disclaimer">
      <li>This does simple text matching. (Therefore we make mistakes and miss some.)</li>
      <li>All of these are suggestions, stay true to yourself.</li>
      <li>None of the text you enter <strong>ever</strong> leaves your computer.</li>
      <li><strong>No AI</strong> usage.</li>
      <li>Results are split by paragraph. We sometimes turn the first letter to a lowercase. (Sorry.)</li>
    </ul>
    <br/><br/>
    <button class="btn-green" v-on:click="vagueTest">Vague Words</button>
    <button class="btn-green" v-on:click="pronounTest">Pronoun Test</button>
    <button class="btn-green" v-on:click="markingCheck">Marking Use</button>
    <!-- <button class="btn-green" v-on:click="itsVsIts">Its vs It's</button> -->
    <button class="btn-green" v-on:click="biasTest">Bias Words</button>
    <br/>
    <button v-on:click="activeTest">Active Voice</button>
    <button v-on:click="ingTest">-ing Test</button>
    <br/>
    <textarea v-model="originalText" placeholder="Paste text to analyze here."></textarea>
    <br/>
    <!-- <button v-on:click="paste">Paste</button> -->
    <button v-on:click="clear">Clear</button>
    <br/>
    <div class="test-description">
      {{ testDescription }}
    </div>
    <br/>
    <div class="analyzed">
      <p v-for="(text, index) in analyzedText" v-html="text"></p>
    </div>
    <br/>
    <button v-if="analyzedText?.length > 0" v-on:click="clear">Clear Text</button>
  </div>
</template>

<script>
//   String.prototype.replaceAll = function(strReplace, strWith) {
//     // See http://stackoverflow.com/a/3561711/556609
//     var esc = strReplace.replace(/[-\/\\^$*+?.()|[\]{}]/g, '\\$&');
//     var reg = new RegExp(esc, 'ig');
//     return this.replace(reg, strWith);
// };

import { ref, watch } from 'vue';
export default {
  data() {
    return {
      originalText: '',
      testDescription: '',
      analyzedText: [],

      pronouns: ["she", "he", "they", "them"],
      vagueWords: [
        // actually vague words
        "things", "stuff", "eventually", "something", "someone", "somehow", "someway", "somewhere", "some", "practically", "literally", "kind of", "a few", "a moment", "anything", "various",
      
        // Words I overuse and are really just excessive. Just remove them.
        "begins", "starts", "watch", "hear", "listen", "just"
      ],
      passiveWords: ["is", "are", "was", "were", "isn't", "isn’t", "wasn't", "wasn’t", "got", "has"],
      passiveEndings: [
        "ed", // like lied
        "en", // like broken
        "de", // like made
        "es", // like does
        "went",
        "un", // like run
        "ought", // like bought
      ],

      // alternatives if you can't think of some: https://blog.ongig.com/diversity-and-inclusion/biased-language-examples/
      biasWords: ["blacklist", "brown bag", "cake walk", "people of color", "confined to a wheelchair", "Degree from a Top School", "Digital Native", "Elderly", "Native Speaker", "Ex-offenders", "Guys", "Grandfathered In", "Gypped", "Gipped", "Handicapped", "Homosexuals", "Illegal Aliens", "Long Time No See", "Mankind", "Man Hours", "Master", "Slave", "Peanut Gallery", "Retard", "Sanity Check", "Spirit Animal", "Tribe", "Bossy", "Salesman", "Crazy", "Lame", "Moron", "Off the reservation", ],

      punctuations: ["?", ",", ".", "\"", "“", "”"]
    }
  },
  methods: {
    // helpers -------------------

    sanitizeString(string) {
      if(!string) return "";

      var result = string;
      for(var i = 0; i < this.punctuations.length; i++) {
        result = result.replaceAll(this.punctuations[i], "");
      }

      return result.toLowerCase();
    },

    stringEnds(string, words) {
      if(!string || !words || !words.length) return false;

      var trimmed = this.sanitizeString(string).toLowerCase();
      for(var i = 0; i < words.length; i++) {
        //console.log("stringEnds", trimmed, words[i])
        if(trimmed.endsWith(words[i].toLowerCase())) {
          return true;
        }
      }
      return false;
    },

    // todo: we do not handle phrases right now ex. "kind of"
    stringHas(string, words, fullMatchOnly = false) {
      if(!string || !words || !words.length) return false;

      var trimmed = this.sanitizeString(string);
      for(var i = 0; i < words.length; i++) {
        if(fullMatchOnly) {
          if(trimmed == words[i].toLowerCase()) {
            return true;
          }
        } else if(trimmed.indexOf(this.sanitizeString(words[i])) >= 0) {
          return true;
        }
      }
      return false;
    },

    // others -------------------

    clear() {
      this.analyzedText = [];
      this.originalText = "";
      this.testDescription = "";
    },

    // paste() {
    //   navigator.clipboard
    //     .readText()
    //     .then((clipText) => (this.originalText = clipText));
    // },

    ingTest() {
      var paragraphs = this.originalText.replaceAll("\t", "").split("\n");
      if(!this.originalText || !paragraphs || paragraphs.length <= 0) {
        this.analyzedText = [];
        this.testDescription = "Please enter text to analyze.";
        return;
      }

      var analyzed = paragraphs.map((paragraph, index) => {
        var words = paragraph.trim().split(" ");
        var highWords = words.map((word, index) => {
          if(this.stringEnds(word, ["ing"])) {
            return "<span class='highlight'>" + word + "</span>";
          } else {
            return word;
          }
        })
        return highWords.join(" ");
      })

      console.log("done!");
      this.testDescription = "Make sure any verbs using -ing actually occur at the same time as another action. Otherwise try to get it into the simple form while keeping the same tense. Note: some false positives might occur like the word 'swing'.";
      this.analyzedText = analyzed;
    },
    
    pronounTest() {
      var paragraphs = this.originalText.replaceAll("\t", "").split("\n");
      if(!this.originalText || !paragraphs || paragraphs.length <= 0) {
        this.analyzedText = [];
        this.testDescription = "Please enter text to analyze.";
        return;
      }

      var analyzed = paragraphs.map((paragraph, index) => {
        var words = paragraph.trim().split(" ");
        var highWords = words.map((word, index) => {
          if(this.stringHas(word, this.pronouns, true)) {
            return "<span class='highlight'>" + word + "</span>";
          } else {
            return word;
          }
        })
        return highWords.join(" ");
      })

      console.log("done!");
      this.testDescription = "Make sure there isn't excessive starting of sentences with a pronoun + filler word. Note: some false positives might occur since we highlight all pronouns, even if in the middle."
      this.analyzedText = analyzed;
    },

    vagueTest() {
      var paragraphs = this.originalText.replaceAll("\t", "").split("\n");
      if(!this.originalText || !paragraphs || paragraphs.length <= 0) {
        this.analyzedText = [];
        this.testDescription = "Please enter text to analyze.";
        return;
      }

      var analyzed = paragraphs.map((paragraph, index) => {
        var updated = paragraph.trim();
        for(var i = 0; i < this.vagueWords.length; i++) {
          updated = updated.replaceAll(this.vagueWords[i], "<span class='highlight'>" + this.vagueWords[i] + "</span>")
        }
        return updated;
      });

      console.log("done!");
      this.testDescription = "Excessive use of vague words can be bland. Try to have fun and make them specific instead.";
      this.analyzedText = analyzed;
    },

    activeTest() {
      var paragraphs = this.originalText.replaceAll("\t", "").split("\n");

      if(!this.originalText || !paragraphs || paragraphs.length <= 0) {
        this.analyzedText = [];
        this.testDescription = "Please enter text to analyze.";
        return;
      }

      // todo we do not handle this: "something was just beyond"

      var analyzed = paragraphs.map((paragraph, index) => {
        var words = paragraph.replaceAll("\t", "").split(" ");

        var transformedText = "";
        for(var i = 0; i < words.length - 1; i++) {
          var currentWord = words[i];
          var nextWord = words[i + 1];

          //console.log("words", words, currentWord, nextWord, this.stringHas(currentWord, this.passiveWords, true), this.stringEnds(nextWord, this.passiveEndings));

          if (this.stringHas(currentWord, this.passiveWords, true) && 
              this.stringEnds(nextWord, this.passiveEndings)) {
                transformedText += "<span class='highlight'>" + currentWord + " " + nextWord + "</span> ";
                i++;
                continue;
          } else {
            transformedText += currentWord + " ";
          }

          if(i == words.length - 2) {
            transformedText += nextWord;
          }
        }
        return transformedText;

        // var highWords = words.map((word, index) => {
        //   if(this.stringHas(word, this.passiveWords, true)) {
        //     return "<span class='highlight'>" + word + "</span>";
        //   } else {
        //     return word;
        //   }
        // })
        // return highWords.join(" ");
      })

      console.log("done!");
      this.testDescription = "Try to remove passive voice by flipping the subject of the sentence. WARNING: we are not great at matching past conjugations. English just has too many, we will miss some.";
      this.analyzedText = analyzed;
    },

    biasTest() {
      var paragraphs = this.originalText.replaceAll("\t", "").split("\n");
      if(!this.originalText || !paragraphs || paragraphs.length <= 0) {
        this.analyzedText = [];
        this.testDescription = "Please enter text to analyze.";
        return;
      }

      var analyzed = paragraphs.map((paragraph, index) => {
        var updated = paragraph.trim();
        for(var i = 0; i < this.biasWords.length; i++) {
          updated = updated.replaceAll(this.biasWords[i], "<span class='highlight'>" + this.biasWords[i] + "</span>")
        }
        return updated;
      });

      console.log("done!");
      this.testDescription = "Remove bias words whenever possible. List is based from (among other places) https://blog.ongig.com/diversity-and-inclusion/biased-language-examples/";
      this.analyzedText = analyzed;
    },

    markingCheck() {
      var paragraphs = this.originalText.replaceAll("\t", "").split("\n");
      if(!this.originalText || !paragraphs || paragraphs.length <= 0) {
        this.analyzedText = [];
        this.testDescription = "Please enter text to analyze.";
        return;
      }

      var analyzed = paragraphs.map((paragraph, index) => {
        var updated = paragraph.trim();
        for(var i = 0; i < this.biasWords.length; i++) {
          updated = updated.replaceAll("\"", "<span class='highlight'>\"</span>");
          updated = updated.replaceAll("“", "<span class='highlight'>“</span>");
          updated = updated.replaceAll("”", "<span class='highlight'>”</span>");
          updated = updated.replaceAll("''", "<span class='highlight-2'>'</span>");
          updated = updated.replaceAll("’", "<span class='highlight-2'>’</span>");
          updated = updated.replaceAll("‘", "<span class='highlight-2'>‘</span>");
          updated = updated.replaceAll("its", "<span class='highlight'>its</span>");
          updated = updated.replaceAll("Its", "<span class='highlight'>Its</span>");
        }
        return updated;
      });

      console.log("done!");
      this.testDescription = "Make sure all quotes have a opening and closing unless there is a multi paragraph quote. (Then only an opening quote mark until the last paragraph.) Double check apostrophe use.";
      this.analyzedText = analyzed;
    },

    itsVsIts() {
      var paragraphs = this.originalText.replaceAll("\t", "").split("\n");
      if(!this.originalText || !paragraphs || paragraphs.length <= 0) {
        this.analyzedText = [];
        this.testDescription = "Please enter text to analyze.";
        return;
      }

      var analyzed = paragraphs.map((paragraph, index) => {
        var words = paragraph.trim().split(" ");
        var highWords = words.map((word, index) => {
          if(this.stringHas(word, ["its", "it's", "it’s"], true)) {
            return "<span class='highlight'>" + word + "</span>";
          } else {
            return word;
          }
        })
        return highWords.join(" ");
      })

      console.log("done!");
      this.testDescription = "It's easy to confuse its meaning with it's. Just double check."
      this.analyzedText = analyzed;
    }
  }
}
</script>

